-- | Application version sourced from the Cabal package metadata.
module ZimToMarkdown.Version (
    appVersion,
    versionText,
) where

import Data.Text (Text)
import Data.Text qualified as Text
import Data.Version (Version, showVersion)
import Paths_zim_to_markdown (version)

-- | The package version generated by Cabal from the @.cabal@ file.
appVersion :: Version
appVersion = version

-- | The package version rendered for command line output.
versionText :: Text
versionText = Text.pack (showVersion appVersion)
